import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"常见误区","description":"按误区类型对照错误说法、原因、正确做法，并链回 TS-AI 手册正文章节","frontmatter":{"title":"常见误区","description":"按误区类型对照错误说法、原因、正确做法，并链回 TS-AI 手册正文章节","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/learning/common-misconceptions.md","filePath":"ts-ai/appendix/learning/common-misconceptions.md","lastUpdated":1786083160000}'),n={name:"ts-ai/appendix/learning/common-misconceptions.md"};function o(s,t,l,d,g,h){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本页按<strong>误区类型</strong>收录 TS-AI 全栈中反复出现的错误判断。每条只回答四件事：错误说法、为什么错、正确做法、回到哪一章。它不是模块目录的镜像，也不代替正文学习。</p><h2 id="_1-这篇怎么用" tabindex="-1">1. 这篇怎么用 <a class="header-anchor" href="#_1-这篇怎么用" aria-label="Permalink to &quot;1. 这篇怎么用&quot;">​</a></h2><h3 id="_1-1-与路线图、清单的边界" tabindex="-1">1.1 与路线图、清单的边界 <a class="header-anchor" href="#_1-1-与路线图、清单的边界" aria-label="Permalink to &quot;1.1 与路线图、清单的边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>附录</th><th>回答的问题</th><th>不负责的问题</th></tr></thead><tbody><tr><td><a href="/ts-ai/appendix/learning/learning-roadmap">学习路线图</a></td><td>先学什么、做到什么程度再继续</td><td>某个判断为什么错</td></tr><tr><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td><td>某能力是否已掌握、证据是什么</td><td>把症状映射到误区</td></tr><tr><td>本文</td><td>这个常见判断为什么错、应回到哪一章纠正</td><td>完整 API、实现步骤或项目交付流程</td></tr></tbody></table><p>用法：先在路线图上定位阶段，用清单勾选能力；出现“明明跑通了却上不了线 / 回答像对了却不可信 / 重连后副作用重复”等症状时，再来本页定位误区并跳回正文。</p><h3 id="_1-2-如何对照症状" tabindex="-1">1.2 如何对照症状 <a class="header-anchor" href="#_1-2-如何对照症状" aria-label="Permalink to &quot;1.2 如何对照症状&quot;">​</a></h3><ol><li>用一句话写出你当前的判断（例如“检索命中了，答案应该没问题”）。</li><li>在第 2–6 章找到最接近的误区类型，不要按模块名硬套。</li><li>读完「为什么错」后，只打开列出的正文章节，补齐缺口再回来核对。</li><li>用第 7 章自检表做二次确认：症状是否消失，或是否落到另一个误区。</li></ol><h2 id="_2-选型误区" tabindex="-1">2. 选型误区 <a class="header-anchor" href="#_2-选型误区" aria-label="Permalink to &quot;2. 选型误区&quot;">​</a></h2><h3 id="_2-1-凡事都用-agent" tabindex="-1">2.1 凡事都用 Agent <a class="header-anchor" href="#_2-1-凡事都用-agent" aria-label="Permalink to &quot;2.1 凡事都用 Agent&quot;">​</a></h3><p><strong>错误说法</strong>：只要调用了大模型，就应该做成 Agent，工具循环越多越智能。</p><p><strong>为什么错</strong>：Agent 引入不确定控制流、工具副作用、预算与停止条件。对固定步骤、强契约或高审计场景，多余循环只会增加成本、延迟和失败面。</p><p><strong>正确做法</strong>：优先选最简单且可验收的形态——普通函数 / Chain → 确定性 Workflow → 需要模型决策时再上 Agent。用任务的确定性、状态、风险和可审计性做选型，而不是用“AI 产品”标签做选型。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a></li><li><a href="/ts-ai/agent/assembly/assembly-recipes-checklist">Agent 组装配方与能力自检</a></li><li><a href="/ts-ai/workflow/workflow-foundations/workflow-principles-boundaries">工作流原理与边界</a></li></ul><h3 id="_2-2-把-workflow-当成可随意跳转的脚本" tabindex="-1">2.2 把 Workflow 当成可随意跳转的脚本 <a class="header-anchor" href="#_2-2-把-workflow-当成可随意跳转的脚本" aria-label="Permalink to &quot;2.2 把 Workflow 当成可随意跳转的脚本&quot;">​</a></h3><p><strong>错误说法</strong>：图节点可以像脚本一样任意 <code>goto</code>；状态随便改，跑不通再补边。</p><p><strong>为什么错</strong>：Workflow 的价值是有限、可观察、可测试的状态迁移。随意跳转会破坏 Reducer 语义、终态定义和重放假设，导致测试与生产路径不一致。</p><p><strong>正确做法</strong>：先建模业务状态、合法转移和终态，再写 Node / Edge；路由条件可单测；循环必须有预算；并发更新必须有明确 Reducer。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/workflow/langgraph-core/workflow-modeling">工作流建模</a></li><li><a href="/ts-ai/workflow/langgraph-core/state-reducers">State 与 Reducer</a></li><li><a href="/ts-ai/workflow/langgraph-core/nodes-edges-routing">Node、Edge 与条件路由</a></li><li><a href="/ts-ai/workflow/workflow-quality/state-transition-testing">状态迁移测试</a></li></ul><h3 id="_2-3-过早上多-agent" tabindex="-1">2.3 过早上多 Agent <a class="header-anchor" href="#_2-3-过早上多-agent" aria-label="Permalink to &quot;2.3 过早上多 Agent&quot;">​</a></h3><p><strong>错误说法</strong>：任务复杂就拆多个 Agent；协作越多越接近“多智能体系统”。</p><p><strong>为什么错</strong>：多 Agent 叠加通信协议、共享状态冲突、终止条件和级联失败。在单 Agent / 单图尚未稳定时引入协作，只会放大调试面，而不是提高质量。</p><p><strong>正确做法</strong>：先用单 Agent 或单图建立可评测基线；只有当职责隔离、并行专家或明确交接能被验收证明有收益时，再引入 Supervisor / Handoff，并定义共享状态与终止条件。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/workflow/multi-agent/multi-agent-patterns">多 Agent 架构模式</a></li><li><a href="/ts-ai/workflow/multi-agent/supervisor-handoff">Supervisor 与 Handoff</a></li><li><a href="/ts-ai/workflow/multi-agent/shared-state-termination">共享状态与终止条件</a></li><li><a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">工作流与多 Agent 组装配方与能力自检</a></li></ul><h2 id="_3-工具与-mcp-误区" tabindex="-1">3. 工具与 MCP 误区 <a class="header-anchor" href="#_3-工具与-mcp-误区" aria-label="Permalink to &quot;3. 工具与 MCP 误区&quot;">​</a></h2><h3 id="_3-1-让模型决定权限与租户" tabindex="-1">3.1 让模型决定权限与租户 <a class="header-anchor" href="#_3-1-让模型决定权限与租户" aria-label="Permalink to &quot;3.1 让模型决定权限与租户&quot;">​</a></h3><p><strong>错误说法</strong>：把 <code>userId</code>、<code>tenantId</code>、角色写进 Prompt 或工具参数，让模型“自己带上正确身份”。</p><p><strong>为什么错</strong>：模型输出不可信，Prompt Injection 可诱导越权。身份与租户属于可信运行时事实，不是模型生成字段。</p><p><strong>正确做法</strong>：由鉴权层解析身份，经请求 Context / Runtime Context 注入工具执行环境；工具内只读取可信 Context，忽略模型传入的身份参数；跨租户访问必须在服务端拒绝。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/agent/tools-mcp/runtime-context-injection">Runtime Context 可信注入</a></li><li><a href="/ts-ai/backend/ai-service/request-context-tenancy">请求 Context 与租户信息</a></li><li><a href="/ts-ai/quality/security-governance/multi-tenancy-isolation">多租户隔离</a></li><li><a href="/ts-ai/quality/security-governance/tool-permissions">工具权限</a></li></ul><h3 id="_3-2-schema-随便、错误直接抛给模型" tabindex="-1">3.2 Schema 随便、错误直接抛给模型 <a class="header-anchor" href="#_3-2-schema-随便、错误直接抛给模型" aria-label="Permalink to &quot;3.2 Schema 随便、错误直接抛给模型&quot;">​</a></h3><p><strong>错误说法</strong>：工具参数 Schema 越松越好；异常栈或原始错误直接塞进 <code>ToolMessage</code>，让模型自己修。</p><p><strong>为什么错</strong>：松 Schema 导致非法调用与副作用风险；原始错误可能泄漏内部细节，也会污染上下文，诱发无效重试循环。</p><p><strong>正确做法</strong>：用清晰 Zod/JSON Schema 约束参数；区分可重试、业务拒绝、未知失败；返回给模型的是结构化、脱敏、限量的结果，而不是堆栈；服务端保留完整诊断日志。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a></li><li><a href="/ts-ai/agent/tools-mcp/tool-errors-timeouts-results">工具错误、超时与结果转换</a></li><li><a href="/ts-ai/agent/models-output/zod-structured-output">Zod 结构化输出</a></li><li><a href="/ts-ai/foundations/model/structured-output-business-validation">结构化输出与业务校验</a></li></ul><h3 id="_3-3-mcp-工具全量暴露给-agent" tabindex="-1">3.3 MCP 工具全量暴露给 Agent <a class="header-anchor" href="#_3-3-mcp-工具全量暴露给-agent" aria-label="Permalink to &quot;3.3 MCP 工具全量暴露给 Agent&quot;">​</a></h3><p><strong>错误说法</strong>：MCP Server 发现了哪些工具，就全部注册给当前 Agent。</p><p><strong>为什么错</strong>：工具面等于攻击面与误用面。无关高权限工具会增加注入收益、提高错误调用概率，也让权限审计失焦。</p><p><strong>正确做法</strong>：按场景、角色和租户筛选注册；默认最小集合；高风险工具单独确认或人在回路；连接、鉴权、超时与服务端异常单独处理。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a></li><li><a href="/ts-ai/agent/tools-mcp/mcp-typescript-sdk">MCP 与 TypeScript SDK</a></li><li><a href="/ts-ai/backend/ai-service/agent-module-tool-registry">Agent Module 与 Tool Registry</a></li><li><a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认与人在回路</a></li></ul><h2 id="_4-rag-与记忆误区" tabindex="-1">4. RAG 与记忆误区 <a class="header-anchor" href="#_4-rag-与记忆误区" aria-label="Permalink to &quot;4. RAG 与记忆误区&quot;">​</a></h2><h3 id="_4-1-检索命中就等于回答正确" tabindex="-1">4.1 检索命中就等于回答正确 <a class="header-anchor" href="#_4-1-检索命中就等于回答正确" aria-label="Permalink to &quot;4.1 检索命中就等于回答正确&quot;">​</a></h3><p><strong>错误说法</strong>：Top-K 有结果，或相似度分数够高，答案就可以直接给用户。</p><p><strong>为什么错</strong>：命中只说明“有相似文本”，不保证证据充分、权限合法、引用一致，或生成没有越证发挥。</p><p><strong>正确做法</strong>：把检索、上下文组装、生成、引用校验分开验收；无证据时明确拒绝或降级；用检索指标 + 答案一致性评测，而不是只看“看起来相关”。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/knowledge/rag-foundations/rag-principles-boundaries">RAG 原理与边界</a></li><li><a href="/ts-ai/knowledge/rag-engineering/citations-sources">引用与来源</a></li><li><a href="/ts-ai/knowledge/retrieval/permission-filtering-retrieval-evaluation">权限过滤与检索评测</a></li><li><a href="/ts-ai/foundations/model/hallucination-injection-verifiable-answers">幻觉、注入与可验证回答</a></li></ul><h3 id="_4-2-chunk-越大越好-只做向量检索" tabindex="-1">4.2 Chunk 越大越好 / 只做向量检索 <a class="header-anchor" href="#_4-2-chunk-越大越好-只做向量检索" aria-label="Permalink to &quot;4.2 Chunk 越大越好 / 只做向量检索&quot;">​</a></h3><p><strong>错误说法</strong>：Chunk 尽量大以免切断语义；有向量库就够了，不必做关键词、过滤或重排。</p><p><strong>为什么错</strong>：过大 Chunk 浪费上下文并降低定位精度；纯向量检索对专有名词、过滤条件和权限场景常失效。</p><p><strong>正确做法</strong>：按文档结构与查询任务选粒度与重叠；组合元数据过滤、混合检索与必要时的 Reranker；用固定评测集证明改动有收益。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/knowledge/document-processing/chunking-strategies">Chunk 策略</a></li><li><a href="/ts-ai/knowledge/retrieval/hybrid-retrieval">混合检索</a></li><li><a href="/ts-ai/knowledge/retrieval/reranking">Reranker</a></li><li><a href="/ts-ai/knowledge/retrieval/similarity-filtering-metadata">相似度、过滤与元数据查询</a></li></ul><h3 id="_4-3-把对话历史当成长期记忆" tabindex="-1">4.3 把对话历史当成长期记忆 <a class="header-anchor" href="#_4-3-把对话历史当成长期记忆" aria-label="Permalink to &quot;4.3 把对话历史当成长期记忆&quot;">​</a></h3><p><strong>错误说法</strong>：把完整聊天记录一直塞进 Prompt，或把 Thread 消息直接当跨会话事实库。</p><p><strong>为什么错</strong>：对话历史是短期上下文；不加裁剪会爆预算、引入过时事实。长期记忆需要显式提取、冲突处理、作用域与删除策略，并与 Checkpoint / Store 区分。</p><p><strong>正确做法</strong>：短期记忆负责当前线程窗口与摘要；值得跨会话保留的事实进入长期记忆 Store；执行快照用 Checkpoint，不把三者混成“一个大数组”。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/knowledge/memory/short-term-memory">短期记忆</a></li><li><a href="/ts-ai/knowledge/memory/long-term-memory">长期记忆</a></li><li><a href="/ts-ai/knowledge/memory/checkpoint-store">Checkpoint 与 Store</a></li><li><a href="/ts-ai/agent/models-output/context-budget-trimming">上下文预算与裁剪</a></li></ul><h2 id="_5-全栈与状态误区" tabindex="-1">5. 全栈与状态误区 <a class="header-anchor" href="#_5-全栈与状态误区" aria-label="Permalink to &quot;5. 全栈与状态误区&quot;">​</a></h2><h3 id="_5-1-前端流式文本即业务完成态" tabindex="-1">5.1 前端流式文本即业务完成态 <a class="header-anchor" href="#_5-1-前端流式文本即业务完成态" aria-label="Permalink to &quot;5.1 前端流式文本即业务完成态&quot;">​</a></h3><p><strong>错误说法</strong>：用户已经看到完整助手文字，说明 Run 成功、业务已落库、副作用已生效。</p><p><strong>为什么错</strong>：流式增量是展示层进展；业务完成取决于服务端终态事件、持久化结果和工具副作用提交。连接中断时，UI 文本可能超前或落后于真实状态。</p><p><strong>正确做法</strong>：以服务端 Run / 事件终态为准；前端区分 generating、tool、completed、failed、cancelled；完成态到来前不触发“已办结”类业务动作。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/integration/ai-interaction/streaming-state-feedback">流式状态与反馈</a></li><li><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">Message、Run 与 Tool Call 事件</a></li><li><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式响应</a></li><li><a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a></li></ul><h3 id="_5-2-thread-run-状态只存在浏览器" tabindex="-1">5.2 Thread/Run 状态只存在浏览器 <a class="header-anchor" href="#_5-2-thread-run-状态只存在浏览器" aria-label="Permalink to &quot;5.2 Thread/Run 状态只存在浏览器&quot;">​</a></h3><p><strong>错误说法</strong>：消息列表和 Run 状态放在前端 store 即可；刷新或换设备后重新聊就行。</p><p><strong>为什么错</strong>：浏览器状态不是事实源。多标签、刷新、扩容实例和客服审计都需要服务端 Thread / Run / Message 模型与可恢复游标。</p><p><strong>正确做法</strong>：PostgreSQL（或等价）持久化 Thread/Run/Message；Redis 只承担缓存与协调；前端状态从服务端事件重建，并处理并发 Run 覆盖。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread、Run 与 Message 数据模型</a></li><li><a href="/ts-ai/integration/vue-nuxt/message-run-state-management">消息与 Run 状态管理</a></li><li><a href="/ts-ai/backend/data-tasks/redis-state-ownership">Redis 与状态所有权</a></li><li><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST Agent API</a></li></ul><h3 id="_5-3-断线重连等于重新执行副作用" tabindex="-1">5.3 断线重连等于重新执行副作用 <a class="header-anchor" href="#_5-3-断线重连等于重新执行副作用" aria-label="Permalink to &quot;5.3 断线重连等于重新执行副作用&quot;">​</a></h3><p><strong>错误说法</strong>：SSE/WebSocket 断了就再调一次 Agent；工具多跑一次也没关系。</p><p><strong>为什么错</strong>：重连是恢复事件流，不是重新提交业务。重复执行可能导致重复扣款、重复工单、重复外部 API 调用。</p><p><strong>正确做法</strong>：客户端带游标/事件 ID 续传并去重；服务端用幂等键保护工具与 Worker；取消信号与“重放节点”语义分开设计。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消、重连与事件去重</a></li><li><a href="/ts-ai/backend/data-tasks/long-tasks-idempotency-recovery">长任务、幂等、取消与恢复</a></li><li><a href="/ts-ai/workflow/durable-execution/idempotency-replay">幂等与重放</a></li><li><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式事件、取消与恢复</a></li></ul><h2 id="_6-质量与生产误区" tabindex="-1">6. 质量与生产误区 <a class="header-anchor" href="#_6-质量与生产误区" aria-label="Permalink to &quot;6. 质量与生产误区&quot;">​</a></h2><h3 id="_6-1-演示成功等于可上线" tabindex="-1">6.1 演示成功等于可上线 <a class="header-anchor" href="#_6-1-演示成功等于可上线" aria-label="Permalink to &quot;6.1 演示成功等于可上线&quot;">​</a></h3><p><strong>错误说法</strong>：Happy path 演示通过，就可以发布；评测和门禁以后再补。</p><p><strong>为什么错</strong>：演示覆盖的是理想输入与人工值守，不覆盖注入、超时、权限、回归漂移和成本失控。没有数据集与阈值，就无法证明下次改动没有变差。</p><p><strong>正确做法</strong>：上线前具备失败样例集、回归门禁、权限与恢复验收；发布清单勾选的是可测量证据，不是“感觉还行”。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/quality/testing-evaluation/evaluation-datasets">评测数据集</a></li><li><a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a></li><li><a href="/ts-ai/architecture/delivery/release-checklist">发布清单</a></li><li><a href="/ts-ai/architecture/delivery/requirements-acceptance">需求与验收标准</a></li></ul><h3 id="_6-2-有-trace-就等于可观测" tabindex="-1">6.2 有 Trace 就等于可观测 <a class="header-anchor" href="#_6-2-有-trace-就等于可观测" aria-label="Permalink to &quot;6.2 有 Trace 就等于可观测&quot;">​</a></h3><p><strong>错误说法</strong>：接了 LangSmith / OpenTelemetry 就算可观测；出问题再去翻 Trace。</p><p><strong>为什么错</strong>：Trace 是诊断原料，不是运营闭环。缺少关联 ID、指标、预算告警和 SLO，仍然无法发现慢、贵、错以及租户级异常。</p><p><strong>正确做法</strong>：结构化日志 + Trace + 指标三联；Thread/Run/租户可关联；跟踪 Token、延迟、成本；定义 SLI/SLO 与降级策略。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/quality/observability-reliability/traces-metrics">Trace 与指标</a></li><li><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a></li><li><a href="/ts-ai/quality/observability-reliability/token-latency-cost">Token、延迟与成本</a></li><li><a href="/ts-ai/quality/observability-reliability/slo-capacity-planning">SLO 与容量规划</a></li></ul><h3 id="_6-3-威胁模型写完就等于安全" tabindex="-1">6.3 威胁模型写完就等于安全 <a class="header-anchor" href="#_6-3-威胁模型写完就等于安全" aria-label="Permalink to &quot;6.3 威胁模型写完就等于安全&quot;">​</a></h3><p><strong>错误说法</strong>：文档里有威胁模型表格，安全工作就完成了。</p><p><strong>为什么错</strong>：威胁模型是假设清单。未落到鉴权、工具权限、注入防护、敏感数据与供应链控制，并经测试验证时，风险仍然存在。</p><p><strong>正确做法</strong>：每个高风险项对应控制措施、验证方式和负责人；持续覆盖 Prompt Injection、越权工具调用、跨租户检索与密钥泄漏；发布前复查未关闭项。</p><p><strong>回到</strong>：</p><ul><li><a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a></li><li><a href="/ts-ai/quality/security-governance/prompt-injection-defense">Prompt Injection 防护</a></li><li><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a></li><li><a href="/ts-ai/quality/security-governance/sensitive-data-auditing">敏感数据与审计</a></li></ul><h2 id="_7-快速自检表" tabindex="-1">7. 快速自检表 <a class="header-anchor" href="#_7-快速自检表" aria-label="Permalink to &quot;7. 快速自检表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能误区</th><th>回到哪一章</th></tr></thead><tbody><tr><td>固定流程却难测、难审计、成本飙升</td><td>2.1 凡事都用 Agent</td><td><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a></td></tr><tr><td>图路径“有时通有时不通”，状态难解释</td><td>2.2 Workflow 当脚本</td><td><a href="/ts-ai/workflow/langgraph-core/workflow-modeling">工作流建模</a></td></tr><tr><td>多角色协作后更难定位失败</td><td>2.3 过早上多 Agent</td><td><a href="/ts-ai/workflow/multi-agent/multi-agent-patterns">多 Agent 架构模式</a></td></tr><tr><td>模型参数里出现租户/用户 ID，或出现跨租户数据</td><td>3.1 模型决定权限与租户</td><td><a href="/ts-ai/agent/tools-mcp/runtime-context-injection">Runtime Context 可信注入</a></td></tr><tr><td>工具乱参、无效重试、日志里堆栈进了模型上下文</td><td>3.2 Schema/错误处理不当</td><td><a href="/ts-ai/agent/tools-mcp/tool-errors-timeouts-results">工具错误、超时与结果转换</a></td></tr><tr><td>Agent 可调用大量无关或高风险 MCP 工具</td><td>3.3 MCP 全量暴露</td><td><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a></td></tr><tr><td>检索有命中但答案无依据或引用对不上</td><td>4.1 命中≠正确</td><td><a href="/ts-ai/knowledge/rag-engineering/citations-sources">引用与来源</a></td></tr><tr><td>专有名词召不回，或上下文又臭又长</td><td>4.2 Chunk/只做向量</td><td><a href="/ts-ai/knowledge/document-processing/chunking-strategies">Chunk 策略</a>、<a href="/ts-ai/knowledge/retrieval/hybrid-retrieval">混合检索</a></td></tr><tr><td>换会话后“记错人”或上下文爆掉</td><td>4.3 历史当长期记忆</td><td><a href="/ts-ai/knowledge/memory/long-term-memory">长期记忆</a></td></tr><tr><td>UI 已显示完整文本，但业务未落库/未办结</td><td>5.1 流式文本当完成态</td><td><a href="/ts-ai/integration/ai-interaction/streaming-state-feedback">流式状态与反馈</a></td></tr><tr><td>刷新丢失线程，或多标签状态互相覆盖</td><td>5.2 状态只在浏览器</td><td><a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread、Run 与 Message 数据模型</a></td></tr><tr><td>重连后重复下单、重复调用外部 API</td><td>5.3 重连=重执行</td><td><a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消、重连与事件去重</a></td></tr><tr><td>演示很好，一上真实流量就漂</td><td>6.1 演示成功=可上线</td><td><a href="/ts-ai/quality/testing-evaluation/regression-gates">回归门禁</a></td></tr><tr><td>有 Trace 仍不知哪类请求变慢变贵</td><td>6.2 有 Trace=可观测</td><td><a href="/ts-ai/quality/observability-reliability/traces-metrics">Trace 与指标</a></td></tr><tr><td>威胁模型文档齐全，但仍可越权或注入成功</td><td>6.3 文档=安全</td><td><a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a>、<a href="/ts-ai/quality/security-governance/tool-permissions">工具权限</a></td></tr></tbody></table><p>对照完成后，用<a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a>勾选对应能力，并用<a href="/ts-ai/appendix/learning/learning-roadmap">学习路线图</a>确认是否需要回到更早阶段补课。</p>',107)])])}const u=a(n,[["render",o]]);export{p as __pageData,u as default};
